import React, { useState, useRef, useEffect, useMemo } from "react";
import Audioplayer from "react-h5-audio-player";
import "react-h5-audio-player/lib/styles.css";
import SearchBar from "./SearchBar";
import { searchSongs, getsongs } from "../api";

const asset = (relativePath) =>
  `${process.env.PUBLIC_URL || ""}${relativePath}`;

const curatedCollection = [
  {
    id: "evare",
    title: "Evare",
    artist: "Vijay Yesudas",
    mood: "Dreamy synthwave",
    duration: "4:34",
    albumArt: asset("/images/premam.jpg"),
    url: asset("/audio/Evare.mp3"),
  },
  {
    id: "vennello-hai-hai",
    title: "Vennello Hai Hai",
    artist: "Hariharan",
    mood: "Late-night acoustic",
    duration: "4:02",
    albumArt: asset("/images/avunuvalliddaruistapaddaru.jpg"),
    url: asset("/audio/VennelloHaiHai.mp3"),
  },
  {
    id: "yemaindho",
    title: "Yemaindho",
    artist: "Karthik",
    mood: "Feel-good pop",
    duration: "3:58",
    albumArt: asset("/images/balupu.jpg"),
    url: asset("/audio/Yemaindho.mp3"),
  },
];

const normalizeSongs = (list = []) => {
  if (!Array.isArray(list) || !list.length) {
    return curatedCollection;
  }

  return list.map((song, index) => {
    const fallback = curatedCollection[index % curatedCollection.length];
    return {
      id: song.id ?? fallback.id ?? `song-${index}`,
      title: song.title ?? fallback.title,
      artist: song.artist ?? fallback.artist,
      mood: song.mood ?? fallback.mood,
      duration: song.duration ?? fallback.duration,
      albumArt: song.albumArt ?? fallback.albumArt,
      url: song.url ?? fallback.url,
      description: song.description ?? fallback.description ?? "",
    };
  });
};

const MusicPlayer = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [library, setLibrary] = useState(curatedCollection);
  const [songs, setSongs] = useState(curatedCollection);
  const [currentSong, setCurrentSong] = useState(curatedCollection[0]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [status, setStatus] = useState({ loading: true, error: null });
  const playerRef = useRef(null);

  useEffect(() => {
    const fetchSongs = async () => {
      try {
        const payload = await getsongs();
        const normalized = normalizeSongs(payload);
        setLibrary(normalized);
        setSongs(normalized);
        setCurrentSong(normalized[0]);
        setStatus({ loading: false, error: null });
      } catch (error) {
        console.error("Error fetching songs:", error);
        setLibrary(curatedCollection);
        setSongs(curatedCollection);
        setCurrentSong(curatedCollection[0]);
        setStatus({
          loading: false,
          error: "Using offline catalogue while the live service recovers.",
        });
      }
    };

    fetchSongs();
  }, []);

  const filteredCount = useMemo(() => songs.length, [songs.length]);

  const handleSearch = async () => {
    const trimmed = searchQuery.trim();

    if (!trimmed) {
      setSongs(library);
      setStatus((prev) => ({ ...prev, error: null }));
      return;
    }

    try {
      const payload = await searchSongs(trimmed);
      const normalized = normalizeSongs(payload);

      if (!normalized.length) {
        throw new Error("No remote matches");
      }

      setSongs(normalized);
      setCurrentSong(normalized[0]);
      setStatus({ loading: false, error: null });
    } catch (error) {
      console.warn("Falling back to local search:", error);
      const localMatches = library.filter((song) => {
        const haystack = `${song.title} ${song.artist} ${song.mood}`.toLowerCase();
        return haystack.includes(trimmed.toLowerCase());
      });

      setSongs(localMatches);
      setStatus({
        loading: false,
        error: localMatches.length
          ? `Showing in-library matches for “${trimmed}”.`
          : `No songs found for “${trimmed}”.`,
      });
    }
  };

  const handleSongClick = (song) => {
    setCurrentSong(song);
    setIsPlaying(true);
  };

  const handlePlay = () => {
    setIsPlaying(true);
  };

  const handlePause = () => {
    setIsPlaying(false);
  };

  const playNextSong = () => {
    if (!songs.length) return;
    const currentIndex = songs.findIndex((song) => song.id === currentSong?.id);
    const nextIndex = (currentIndex + 1) % songs.length;
    setCurrentSong(songs[nextIndex]);
  };

  const playPreviousSong = () => {
    if (!songs.length) return;
    const currentIndex = songs.findIndex((song) => song.id === currentSong?.id);
    const prevIndex = (currentIndex - 1 + songs.length) % songs.length;
    setCurrentSong(songs[prevIndex]);
  };

  const heroSubtitle = isPlaying
    ? "Streaming in studio-grade clarity."
    : "Select a track to start your private session.";

  return (
    <section className="player-root">
      <div className="player-hero glass-panel">
        <div className="hero-content">
          <p className="eyebrow">NovaWave Studios</p>
          <h1>Official Listening Suite</h1>
          <p className="hero-copy">
            Experience a premium, editorially curated queue that blends timeless Telugu hits
            with modern soundscapes. Crafted for launch events, lounges, and late-night focus
            sessions.
          </p>
          <div className="player-metrics">
            <div>
              <p className="metric-label">Session status</p>
              <strong>{isPlaying ? "Live playback" : "Standby"}</strong>
            </div>
            <div>
              <p className="metric-label">Library size</p>
              <strong>{filteredCount} tracks</strong>
            </div>
            <div>
              <p className="metric-label">Audio engine</p>
              <strong>HD 48 kHz</strong>
            </div>
          </div>
        </div>
        <div className="hero-art">
          <img
            src={currentSong?.albumArt || asset("/logo.png")}
            alt={currentSong?.title || "Album art"}
            loading="lazy"
          />
          <div className="hero-track">
            <p className="eyebrow">{currentSong?.mood || "Curated for you"}</p>
            <strong>{currentSong?.title || "Select a track"}</strong>
            <span>{currentSong?.artist || heroSubtitle}</span>
          </div>
        </div>
      </div>

      <SearchBar
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
        onSearch={handleSearch}
        placeholder="Search across the catalogue"
      />

      {status.error && (
        <p className="status-banner" role="status">
          {status.error}
        </p>
      )}

      <div className="player-body">
        <div className="now-playing-card glass-panel">
          <div className="player-header">
            <div>
              <p className="eyebrow">{isPlaying ? "Now playing" : "Paused"}</p>
              <h2>{currentSong?.title || "No track selected"}</h2>
              <p>{currentSong?.artist || "Pick a card from the playlist to begin."}</p>
            </div>
            <div className="track-tags">
              {currentSong?.mood && <span className="tag subtle">{currentSong.mood}</span>}
              {currentSong?.duration && (
                <span className="tag subtle">{currentSong.duration}</span>
              )}
            </div>
          </div>

          <Audioplayer
            autoPlayAfterSrcChange
            showSkipControls
            showJumpControls={false}
            onClickNext={playNextSong}
            onClickPrevious={playPreviousSong}
            onEnded={playNextSong}
            src={currentSong?.url || ""}
            onPlay={handlePlay}
            onPause={handlePause}
            ref={playerRef}
          />
        </div>

        <div className="playlist-panel glass-panel">
          <div className="playlist-header">
            <p className="eyebrow">Curated queue</p>
            <span>{filteredCount} tracks</span>
          </div>

          {status.loading ? (
            <p className="empty-state">Loading the catalogue...</p>
          ) : songs.length ? (
            <div className="song-list">
              {songs.map((song) => (
                <button
                  type="button"
                  key={song.id}
                  onClick={() => handleSongClick(song)}
                  className={`song-card ${currentSong?.id === song.id ? "active" : ""}`}
                >
                  <img src={song.albumArt} alt="" aria-hidden="true" />
                  <div className="song-info">
                    <strong>{song.title}</strong>
                    <p>{song.artist}</p>
                  </div>
                  <div className="song-meta">
                    {song.mood && <span className="tag subtle">{song.mood}</span>}
                    {song.duration && <span className="song-duration">{song.duration}</span>}
                  </div>
                </button>
              ))}
            </div>
          ) : (
            <p className="empty-state">
              No songs match this search yet. Try a different artist or mood.
            </p>
          )}
        </div>
      </div>
    </section>
  );
};

export default MusicPlayer;
